120	void IAST::FormatSettings::writeIdentifier(const String & name) const
121	{
122	    switch (identifier_quoting_style)
123	    {
124	        case IdentifierQuotingStyle::None:
125	        {
126	            if (always_quote_identifiers)
127	                throw Exception("Incompatible arguments: always_quote_identifiers = true && identifier_quoting_style == IdentifierQuotingStyle::None",
128	                    ErrorCodes::BAD_ARGUMENTS);
129	            writeString(name, ostr);
130	            break;
131	        }
132	        case IdentifierQuotingStyle::Backticks:
133	        {
134	            if (always_quote_identifiers)
135	                writeBackQuotedString(name, ostr);
136	            else
137	                writeProbablyBackQuotedString(name, ostr);
138	            break;
139	        }
140	        case IdentifierQuotingStyle::DoubleQuotes:
141	        {
142	            if (always_quote_identifiers)
143	                writeDoubleQuotedString(name, ostr);
144	            else
145	                writeProbablyDoubleQuotedString(name, ostr);
146	            break;
147	        }
148	        case IdentifierQuotingStyle::BackticksMySQL:
149	        {
150	            if (always_quote_identifiers)
151	                writeBackQuotedStringMySQL(name, ostr);
152	            else
153	                writeProbablyBackQuotedStringMySQL(name, ostr);
154	            break;
155	        }
156	    }
157	}
