159	void IAST::dumpTree(WriteBuffer & ostr, size_t indent) const
160	{
161	    String indent_str(indent, '-');
162	    ostr << indent_str << getID() << ", ";
163	    writePointerHex(this, ostr);
164	    writeChar('\n', ostr);
165	    for (const auto & child : children)
166	    {
167	        if (!child) throw Exception("Can't dump nullptr child", ErrorCodes::UNKNOWN_ELEMENT_IN_AST);
168	        child->dumpTree(ostr, indent + 1);
169	    }
170	}
