113	    template <typename T>
114	    void set(T * & field, const ASTPtr & child)
115	    {
116	        if (!child)
117	            return;
118	
119	        T * casted = dynamic_cast<T *>(child.get());
120	        if (!casted)
121	            throw Exception("Could not cast AST subtree", ErrorCodes::LOGICAL_ERROR);
122	
123	        children.push_back(child);
124	        field = casted;
125	    }
126	
127	    template <typename T>
128	    void replace(T * & field, const ASTPtr & child)
129	    {
130	        if (!child)
131	            throw Exception("Trying to replace AST subtree with nullptr", ErrorCodes::LOGICAL_ERROR);
132	
133	        T * casted = dynamic_cast<T *>(child.get());
134	        if (!casted)
135	            throw Exception("Could not cast AST subtree", ErrorCodes::LOGICAL_ERROR);
136	
137	        for (ASTPtr & current_child : children)
138	        {
139	            if (current_child.get() == field)
140	            {
141	                current_child = child;
142	                field = casted;
143	                return;
144	            }
145	        }
146	
147	        throw Exception("AST subtree not found in children", ErrorCodes::LOGICAL_ERROR);
148	    }
149	
150	    template <typename T>
151	    void setOrReplace(T * & field, const ASTPtr & child)
152	    {
153	        if (field)
154	            replace(field, child);
155	        else
156	            set(field, child);
157	    }
158	
159	    template <typename T>
160	    void reset(T * & field)
161	    {
162	        if (field == nullptr)
163	            return;
164	
165	        const auto child = std::find_if(children.begin(), children.end(), [field](const auto & p)
166	        {
167	           return p.get() == field;
168	        });
169	
170	        if (child == children.end())
171	            throw Exception("AST subtree not found in children", ErrorCodes::LOGICAL_ERROR);
172	
173	        children.erase(child);
174	        field = nullptr;
175	    }
