278	template <typename AstArray>
279	std::string IAST::formatForErrorMessage(const AstArray & array)
280	{
281	    WriteBufferFromOwnString buf;
282	    for (size_t i = 0; i < array.size(); ++i)
283	    {
284	        if (i > 0)
285	        {
286	            const char * delim = ", ";
287	            buf.write(delim, strlen(delim));
288	        }
289	        array[i]->format(IAST::FormatSettings(buf, true /* one line */));
290	    }
291	    return buf.str();
292	}
